const body = $input.first().json.body || $input.first().json;
const items = body.items || [];
const storeId = body.storeId;

const alerts = [];
const poLineItems = [];
let totalEstimatedCost = 0;

items.forEach(item => {
  const stock = Number(item.stockQuantity) || 0;
  const threshold = Number(item.reorderThreshold) || 10;
  const velocity30 = Number(item.salesVelocity30Days) || 0;
  const dailyVelocity = velocity30 > 0 ? (velocity30 / 30) : 0.5;
  const runwayDays = Math.round(stock / dailyVelocity);
  const costPrice = Number(item.costPrice) || Math.round((Number(item.price) || 1000) * 0.45);

  // Check if reorder triggered
  if (stock <= threshold || runwayDays <= 14) {
    // Target 45 days of buffer stock
    const targetStock = Math.ceil(dailyVelocity * 45);
    const suggestedQty = Math.max(targetStock - stock, 15);
    const estimatedCost = suggestedQty * costPrice;
    totalEstimatedCost += estimatedCost;

    alerts.push({
      productId: item.id || item._id,
      title: item.title,
      sku: item.sku,
      currentStock: stock,
      threshold,
      runwayDays,
      dailyVelocity: Number(dailyVelocity.toFixed(2)),
      severity: runwayDays <= 5 ? 'CRITICAL' : 'WARNING'
    });

    poLineItems.push({
      productId: item.id || item._id,
      title: item.title,
      sku: item.sku,
      suggestedQuantity: suggestedQty,
      costPrice,
      estimatedCost
    });
  }
});

const poNumber = `PO-${Date.now().toString().slice(-6)}`;
const defaultSupplier = {
  name: 'Apex Apparel & Textile Mills',
  email: 'orders@apextextiles.in',
  leadTimeDays: 7
};

return {
  json: {
    storeId,
    scannedProductsCount: items.length,
    alertsCount: alerts.length,
    alerts,
    purchaseOrderDraft: poLineItems.length > 0 ? {
      poNumber,
      supplier: defaultSupplier,
      items: poLineItems,
      totalEstimatedCost,
      status: 'DRAFT_PENDING_APPROVAL'
    } : null,
    summary: alerts.length > 0 
      ? `Identified ${alerts.length} SKU(s) requiring inventory replenishment. Generated draft purchase order ${poNumber}.`
      : 'All product inventory runways are healthy (> 14 days). No replenishment needed.',
    timestamp: new Date().toISOString()
  }
};
